using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Generic;
public static class OfficialObservationPresentation{
 static string S(Dictionary<string,object>d,string k){object v;return d.TryGetValue(k,out v)&&v!=null?Convert.ToString(v):"unknown";}
 static IEnumerable<object>A(Dictionary<string,object>d,string k){object v;if(d.TryGetValue(k,out v)&&v is IEnumerable&&!(v is string)&&!(v is IDictionary))foreach(var x in(IEnumerable)v)yield return x;}
 public static string Describe(string root,string candidate,string revision){string path=Path.Combine(root,"official-observations.json");if(!File.Exists(path))return "";try{if(Path.GetFullPath(path).StartsWith(@"\\"))throw new IOException("Local observations only");for(var dir=new DirectoryInfo(root);dir!=null;dir=dir.Parent)if((dir.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("Reparse observation path");if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Reparse observation file");var report=LocalJson.ReadObject(path);if(S(report,"schema")!="reveng-structured-official-projection-v1")throw new IOException("Unknown projection schema");var pins=report["candidate_pins"]as Dictionary<string,object>;if(candidate!=null&&(pins==null||S(pins,candidate)!=revision))return "Structured official update belongs to another candidate revision; reimport required.\r\n";
 var b=new StringBuilder("НОВЫЕ СТРУКТУРИРОВАННЫЕ НАБЛЮДЕНИЯ — отдельный слой, не полный исходный документ.\r\nИсторические тарифы ниже не заполняют неизвестные новые поля. Решения владельца не обновлены.\r\n");
 b.AppendLine("Обзор поставщиков; их функции не назначены автоматически альтернативами этой карточки.");
 foreach(var item in A(report,"projections")){var p=item as Dictionary<string,object>;if(p==null)continue;b.AppendLine(S(p,"vendor")+" | "+S(p,"url")+" | получено "+S(p,"retrieved_at_utc"));b.AppendLine("Origin: "+S(p,"evidence_origin")+"; raw spans: NONE; local observation SHA256: "+S(p,"local_observation_sha256"));b.AppendLine("Currency: "+S(p,"currency")+" | additional user charge: "+S(p,"additional_user_charge"));if(p.ContainsKey("promo_status"))b.AppendLine("Promo: "+S(p,"promo_status")+"; promo_is_current_price: "+S(p,"promo_is_current_price"));if(p.ContainsKey("function_distinction"))b.AppendLine(S(p,"function_distinction"));if(p.ContainsKey("additional_user_charge_status"))b.AppendLine(S(p,"additional_user_charge_status"));b.AppendLine("Task equivalence: "+S(p,"task_equivalence"));foreach(var e in A(p,"evidence")){var evidence=e as Dictionary<string,object>;if(evidence!=null)b.AppendLine("Tool-extracted lines (not raw offsets): "+S(evidence,"lines")+" | "+S(evidence,"kind"));}}
 return b.ToString();}catch(Exception e){if(e is OutOfMemoryException)throw;return "Official structured observations unavailable: "+e.GetType().Name+"; historical values are not a substitute.\r\n";}}
}
